pub(crate) fn scalar_spec_controlled<C: NativeSchemaControl, const N: usize>(keyword: Option<&str>, layout: RecordLayout, definitions: [(u16, &str, Shape); N], control: &mut C) -> Result<RecordSpec, semio_framework_value::ValueError> {
    control.scoped_stage(|control| {
        control.begin_stage(N)?;
        let mut fields = control.allocate_vec(N)?;
        for (id, key, shape) in definitions {
            fields.push(producer::field(id, key, shape, control)?);
            control.step()?;
        }
        producer::record(keyword, layout, fields, control)
    })
}

